sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    try {

        var r = new sn_ws.RESTMessageV2('x_1819012_colbur_0.x_1819012_colbur_0.ColburnIncident', 'Create Incident Colburn');

        //override authentication profile 
        //authentication type ='basic'/ 'oauth2'
        //r.setAuthenticationProfile(authentication type, profile name);

        //set a MID server name if one wants to run the message on MID
        //r.setMIDServer('MY_MID_SERVER');

        //if the message is configured to communicate through ECC queue, either
        //by setting a MID server or calling executeAsync, one needs to set skip_sensor
        //to true. Otherwise, one may get an intermittent error that the response body is null
        //r.setEccParameter('skip_sensor', true);

        var body = {
            "short_description": current.getValue("short_description"),
            "state": current.getValue("state"),
            "description": current.getValue("description"),
			"correlation_display": current.getValue("number"),
			"correlation_id": current.getUniqueValue()
        };

        r.setRequestBody(JSON.stringify(body));

        var response = r.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

		if (httpStatus >= 200 && httpStatus < 300 && responseBody) {
			var data;
			try { data = JSON.parse(responseBody); }
			catch (e) {
				data = null;
			}
			if (data && data.result) {
				current.setWorkflow(false);
				if (data.result.number) {
					current.setValue("correlation_display", data.result.number);
				}
				if (data.result.sys_id) {
					current.setValue("correlation_id", data.result.sys_id);
				}
				current.update();
			}
		}
    } catch (ex) {
        var message = ex.message;
    }

})(current, previous);
